// Helper functions

export function getCruiseLines(): string[] {
  return [...new Set(CRUISE_SHIPS.map((s) => s.cruiseLine))].sort();
}

export function getShipByCruiseLine(cruiseLine: string): CruiseShip[] {
  return CRUISE_SHIPS.filter((s) => s.cruiseLine === cruiseLine);
}

export function searchShips(query: string): CruiseShip[] {
  const q = query.toLowerCase();
  return CRUISE_SHIPS.filter(
    (s) =>
      s.name.toLowerCase().includes(q) ||
      s.imo.includes(q) ||
      s.cruiseLine.toLowerCase().includes(q) ||
      s.flag.toLowerCase().includes(q)
  );
}

